functions.cleanup_notifications:
def cleanup_notifications():
    """Delete expired and old terminal notification rows in bounded batches."""
    now = frappe.utils.now_datetime()
    deleted = {"expired": 0, "dismissed": 0, "read": 0}

    policies = (
        ("expired", {"expires_on": ["<=", now]}),
        (
            "dismissed",
            {
                "is_dismissed": 1,
                "dismissed_on": [
                    "<=",
                    frappe.utils.add_to_date(now, days=-30),
                ],
            },
        ),
        (
            "read",
            {
                "is_read": 1,
                "read_on": [
                    "<=",
                    frappe.utils.add_to_date(now, days=-180),
                ],
            },
        ),
    )

    deleted_names = set()
    for key, filters in policies:
        names = frappe.get_all(
            "OMC Notification",
            filters=filters,
            pluck="name",
            limit_page_length=500,
        )
        for name in names:
            if name in deleted_names:
                continue
            frappe.delete_doc(
                "OMC Notification",
                name,
                ignore_permissions=True,
                force=True,
            )
            deleted_names.add(name)
            deleted[key] += 1

    if deleted_names:
        frappe.db.commit()

    deleted["total"] = len(deleted_names)
    return deleted

